def contains(poly, x, y):
    inside = False
    x1, y1 = poly[-1]
    for x2, y2 in poly:
        if (y1 > y) != (y2 > y) and x < (x2-x1)*(y-y1)/(y2-y1)+x1:
            inside = not inside
        x1, y1 = x2, y2
    return inside

out = Path('outputs')
out.mkdir(exist_ok=True)
matrix = [[int(any(contains(p, lon, lat) for p in polygons))
           for lon in range(-179, 180, 2)] for lat in range(89, -90, -2)]
with (out / 'candidate.csv').open('w', newline='', encoding='ascii') as f:
    csv.writer(f).writerows(matrix)
image = Image.new('L', (180, 90))
image.putdata([255*v for row in matrix for v in row])
image.save(out / 'candidate.png')
image.resize((1440, 720), Image.Resampling.NEAREST).save(out / 'candidate_8x.png')
assert len(matrix) == 90 and all(len(row) == 180 and set(row) <= {0, 1} for row in matrix)
assert set(image.getdata()) <= {0, 255}
large = Image.open(out / 'candidate_8x.png')
assert large.size == (1440, 720)
assert all(large.getpixel((x, y)) == image.getpixel((x//8, y//8)) for y in range(720) for x in range(1440))
